{
  "name": "opencode-go-limit",
  "version": "1.1.0",
  "private": true,
  "description": "OpenCode plugin that shows the OpenCode Go plan usage limits (5-hour, weekly and monthly windows) in a dialog when you run /limit.",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "go",
    "usage",
    "limits"
  ],
  "exports": {
    ".": "./src/index.ts",
    "./server": "./src/index.ts",
    "./tui": "./src/tui.tsx",
    "./rpc": "./src/rpc.ts"
  },
  "files": [
    "src",
    "README.md"
  ],
  "scripts": {
    "test": "node --test test/*.test.js"
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.1"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  }
}
